package app.bean.focus;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import java.io.*;import java.net.*;import java.security.*;
public class UpdateActivity extends Activity {
 private EditText url;private TextView status;private Button download,pick,install;private boolean busy,ready;
 protected void onCreate(Bundle b){super.onCreate(b);ScrollView scroll=new ScrollView(this);scroll.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(28,28,28,40);scroll.addView(body);setContentView(scroll);
  TextView title=new TextView(this);title.setText("집중콩 업데이트");title.setTextSize(26);body.addView(title);TextView help=new TextView(this);help.setText("휴대폰에서 최신 집중콩 APK를 내려받아 설치합니다. 공식 배포 주소가 기본 등록되어 있습니다. 설치 시 Android 확인이 필요하며, 집중 잠금이 끝난 상태에서 진행하세요.");body.addView(help);
  url=new EditText(this);url.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);url.setHint("고정 HTTPS APK 주소");url.setText(UpdateRules.address(Prefs.get(this).getString("update_apk_url","")));body.addView(url);
  download=button(body,"최신 버전 다운로드",()->download());pick=button(body,"다운로드한 APK 파일 선택",()->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/vnd.android.package-archive","application/octet-stream"}),4);}catch(RuntimeException e){message("파일 선택기를 열지 못했어요");}});
  install=button(body,"확인한 업데이트 설치",()->install());install.setEnabled(false);status=new TextView(this);status.setText("GitHub 배포 주소가 연결되어 있습니다. 최신 버전을 다운로드하세요. 앱 ID·기존 서명 인증서·버전을 확인하며, 이미 같은 버전이면 설치하지 않습니다.");body.addView(status);button(body,"닫기",()->finish());
 }
 private Button button(LinearLayout body,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setOnClickListener(v->action.run());body.addView(b);return b;}
 private void message(String text){status.setText(text);}
 private void work(Source source){if(busy)return;busy=true;ready=false;download.setEnabled(false);pick.setEnabled(false);install.setEnabled(false);message("업데이트 파일 확인 중…");new Thread(()->{String result;boolean accepted=false;try{File temp=new File(getFilesDir(),"beanfocus-update.part");try(InputStream in=source.open();OutputStream out=new FileOutputStream(temp)){byte[] bytes=new byte[32768];long count=0;int n;while((n=in.read(bytes))!=-1){count+=n;if(count>UpdateRules.LIMIT)throw new IOException("업데이트 파일이 25MB를 넘어요");out.write(bytes,0,n);}}
   PackageManager pm=getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo info=pm.getPackageArchiveInfo(temp.getAbsolutePath(),flags);if(info==null)throw new IOException("APK를 읽을 수 없어요");android.content.pm.Signature[] certs=Build.VERSION.SDK_INT>=28&&info.signingInfo!=null?info.signingInfo.getApkContentsSigners():info.signatures;if(certs==null||certs.length!=1)throw new IOException("업데이트 서명을 확인할 수 없어요");byte[] hash=MessageDigest.getInstance("SHA-256").digest(certs[0].toByteArray());StringBuilder sha=new StringBuilder();for(byte v:hash)sha.append(String.format(java.util.Locale.ROOT,"%02x",v&255));long next=Build.VERSION.SDK_INT>=28?info.getLongVersionCode():info.versionCode;PackageInfo local=pm.getPackageInfo(getPackageName(),0);long current=Build.VERSION.SDK_INT>=28?local.getLongVersionCode():local.versionCode;if(DeviceConstants.OWN.equals(info.packageName)&&UpdateRules.CERT.equalsIgnoreCase(sha.toString())&&next==current)throw new IOException("이미 최신 버전을 사용 중이에요.");if(!UpdateRules.compatible(info.packageName,sha.toString(),next,current))throw new IOException("현재보다 새 버전인 같은 집중콩 앱·서명만 설치할 수 있어요");
   File apk=UpdateFileProvider.apk(this);try(InputStream in=new FileInputStream(temp);OutputStream out=new FileOutputStream(apk)){byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}temp.delete();accepted=true;result="새 버전 "+info.versionName+" 확인 완료 · Android 설치 확인을 진행하세요.";
  }catch(Exception e){result=e.getMessage()==null?"업데이트 파일 확인 실패":e.getMessage();}final String text=result;final boolean ok=accepted;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;busy=false;ready=ok;download.setEnabled(true);pick.setEnabled(true);install.setEnabled(ok);message(text);});},"bean-update").start();}
 private interface Source {InputStream open()throws Exception;}
 private void download(){String address=UpdateRules.address(url.getText().toString());if(!UpdateRules.https(address)){message("HTTPS APK 주소를 입력하세요");return;}Prefs.get(this).edit().putString("update_apk_url",address).apply();work(()->httpsStream(address));}
 private InputStream httpsStream(String address)throws Exception{for(int i=0;i<6;i++){if(!UpdateRules.https(address))throw new IOException("HTTPS 주소만 허용해요");HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setUseCaches(false);int code=c.getResponseCode();if(code>=300&&code<400){String redirect=c.getHeaderField("Location");URL next=new URL(new URL(address),redirect);c.disconnect();address=next.toString();continue;}if(code!=200){c.disconnect();throw new IOException("다운로드 실패: HTTP "+code);}if(c.getContentLengthLong()>UpdateRules.LIMIT){c.disconnect();throw new IOException("파일 크기 제한 초과");}return new FilterInputStream(c.getInputStream()){public void close()throws IOException{try{super.close();}finally{c.disconnect();}}};}throw new IOException("주소 이동 횟수 초과");}
 private void install(){if(!ready)return;if(FocusLock.active(this)){message("집중 잠금이 끝나거나 10분 조기 해제 후 설치하세요. 다운로드한 파일은 유지됩니다.");return;}try{if(!getPackageManager().canRequestPackageInstalls()){startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));message("집중콩의 앱 설치를 허용한 뒤 설치 버튼을 다시 누르세요.");return;}Uri uri=Uri.parse("content://"+getPackageName()+".update/beanfocus-update.apk");startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(RuntimeException e){message("설치 확인 화면을 열지 못했어요. 기기에서 허용되는 설치 설정을 확인하세요.");}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==4&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();work(()->getContentResolver().openInputStream(uri));}}
}
